<template>
  <div class="page-heading"><div><h1 class="page-title">推广账户</h1><p>管理推广项目、渠道和账户信息。</p></div><el-button type="primary" @click="open()">添加账户</el-button></div>
  <div class="content-panel"><el-table :data="accounts" border v-loading="loading"><el-table-column prop="project" label="项目" width="100" /><el-table-column prop="platform" label="渠道" width="140" /><el-table-column prop="name" label="账户名称" min-width="180" /><el-table-column prop="accountNo" label="户号" min-width="160" /><el-table-column prop="remark" label="备注" min-width="180" show-overflow-tooltip /><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status === 'ACTIVE' ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div>
  <el-dialog v-model="visible" :title="form.id ? '编辑推广账户' : '添加推广账户'" width="520px"><el-form :model="form" label-width="90px"><el-form-item label="项目" required><el-radio-group v-model="form.project"><el-radio value="重庆">重庆</el-radio><el-radio value="绵阳">绵阳</el-radio></el-radio-group></el-form-item><el-form-item label="渠道" required><el-input v-model="form.platform" placeholder="如：腾讯广告、巨量引擎、本地推" /></el-form-item><el-form-item label="账户名称" required><el-input v-model="form.name" /></el-form-item><el-form-item label="户号"><el-input v-model="form.accountNo" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="ACTIVE">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="visible = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { createPromotionAccount, deletePromotionAccount, getPromotionAccounts, type PromotionAccountItem, updatePromotionAccount } from '../api/admin';
const accounts = ref<PromotionAccountItem[]>([]); const loading = ref(false); const saving = ref(false); const visible = ref(false); const blank = () => ({ id: '', project: '重庆' as '重庆' | '绵阳', platform: '', name: '', accountNo: '', status: 'ACTIVE' as 'ACTIVE' | 'DISABLED', remark: '' }); const form = reactive(blank());
async function load() { loading.value = true; try { accounts.value = await getPromotionAccounts(); } finally { loading.value = false; } }
function open(row?: PromotionAccountItem) { Object.assign(form, blank(), row || {}); visible.value = true; }
async function save() { if (!form.name.trim() || !form.platform.trim()) return ElMessage.warning('请填写渠道和账户名称'); saving.value = true; try { const { id, ...data } = form; if (id) await updatePromotionAccount(id, data); else await createPromotionAccount(data); ElMessage.success('账户已保存'); visible.value = false; await load(); } finally { saving.value = false; } }
async function remove(row: PromotionAccountItem) { await ElMessageBox.confirm(`删除账户“${row.name}”会同时删除其全部日数据，确认继续吗？`, '删除确认', { type: 'warning' }); await deletePromotionAccount(row.id); ElMessage.success('已删除'); await load(); }
onMounted(load);
</script>
<style scoped>.page-heading { display:flex; justify-content:space-between; align-items:flex-start; gap:16px; margin-bottom:20px; }.page-title { margin:0 0 6px; }.page-heading p { margin:0; color:var(--admin-text-muted); }</style>
